# Create a temporary test file in /tmp/test_new.py
cat <<EOF > /tmp/test_new.py
from app.api.handlers import handle_filter_users

def test_filter_users_ok():
    code, resp = handle_filter_users({"where": "name == 'Ada'"})
    assert code == 200
    assert resp == {"users": [{"id": 1, "name": "Ada", "email": "ada@example.com"}]}

def test_filter_users_and():
    code, resp = handle_filter_users({"where": "id > 1 and email != 'ada@example.com'"})
    assert code == 200
    assert resp == {"users": [{"id": 2, "name": "Linus", "email": "linus@example.com"}]}

def test_filter_users_invalid_syntax():
    code, resp = handle_filter_users({"where": "name == "})
    assert code == 400
    assert resp == {"error": "invalid filter"}

def test_filter_users_invalid_field():
    code, resp = handle_filter_users({"where": "foo == 1"})
    assert code == 400
    assert resp == {"error": "invalid filter"}

def test_filter_users_missing():
    code, resp = handle_filter_users({})
    assert code == 400
    assert resp == {"error": "invalid filter"}
EOF

# Run pytest on the temporary file
export PYTHONPATH=$PYTHONPATH:.
pytest /tmp/test_new.py
